/**  Une ligne du tableau profil / local de `IdentityMismatch`. */
export type SettingRowView_Serialize = {
	setting: string,
	profile: string,
	/**  `None` : réglage absent du `.git/config` local. */
	local: string | null,
	differs: boolean,
};

